async function psave(id) {
  const o = $('#layer .sheet'), g = n => o.querySelector(`[name=${n}]`), name = g('name').value.trim(); if (!name) return toast('Falta el nombre');
  const p = { id: id || name.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') + '-' + Math.random().toString(36).slice(2, 5), name, cat: g('cat').value, door: g('door').value, size: g('size').value, price: +g('price').value || 0, stock: +g('stock').value || 0, img: g('img').value.trim(), active: g('active').checked, best: g('best').checked, pick: g('pick').checked, type: g('type').value, grape: g('grape').value, country: g('country').value, note: g('note').value, occ: [...o.querySelectorAll('[name=occ]:checked')].map(x => x.value) };
  await Data.saveProduct(p); closeOv(); toast('Producto guardado'); view();
}
